<template>
<h6 class="mb-3 mt-2">User Remarks</h6>
  <div v-if="logsLoading" class="text-center py-2">
    <span v-html="waitIndicator()"></span>
  </div>

    <div v-else class="d-flex flex-column gap-2" >
    <template v-for="log in logs" :key="log.id">
      <!-- parent -->
      <div class="d-flex gap-2 align-items-start">
        <div class="avatar-circle avatar-sm flex-shrink-0"
             :style="{ background: avatarBg(log.reporter?.name), color: avatarColor(log.reporter?.name) }">
          {{ log.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:13px;">{{ log.reporter?.name }}</strong>
            <small class="text-muted">{{ formatDate(log.created_at) }}</small>
          </div>
          <p style="font-size:13px;margin:0;">{{ log.description }}</p>
        </div>
      </div>

      <!-- replies (level 2), flattened, indented -->
      <div v-for="reply in log.replies || []" :key="reply.id" class="d-flex gap-2 align-items-start ms-4">
        <div class="avatar-circle avatar-xs flex-shrink-0"
             :style="{ background: avatarBg(reply.reporter?.name), color: avatarColor(reply.reporter?.name) }">
          {{ reply.reporter?.name?.charAt(0)?.toUpperCase() }}
        </div>
        <div class="flex-grow-1">
          <div class="d-flex align-items-center gap-2 flex-wrap">
            <strong style="font-size:12px;">{{ reply.reporter?.name }}</strong>
            <small class="text-muted" style="font-size:11px;">{{ formatDate(reply.created_at) }}</small>
          </div>
          <p style="font-size:12px;margin:0;">{{ reply.description }}</p>
        </div>
      </div>

      <!-- nested replies (level 3), flattened further -->
      <div v-for="reply in log.replies || []" :key="'n-' + reply.id">
        <div v-for="nested in reply.replies || []" :key="nested.id" class="d-flex gap-2 align-items-start ms-5">
          <div class="avatar-circle avatar-xs flex-shrink-0"
               :style="{ background: avatarBg(nested.reporter?.name), color: avatarColor(nested.reporter?.name) }">
            {{ nested.reporter?.name?.charAt(0)?.toUpperCase() }}
          </div>
          <div class="flex-grow-1">
            <div class="d-flex align-items-center gap-2 flex-wrap">
              <strong style="font-size:11px;">{{ nested.reporter?.name }}</strong>
              <small class="text-muted" style="font-size:10px;">{{ formatDate(nested.created_at) }}</small>
            </div>
            <p style="font-size:11px;margin:0;">{{ nested.description }}</p>
          </div>
        </div>
      </div>
    </template>
  </div>





</template>


<script setup>
    import { onMounted, ref, inject, watch, computed } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    useMeta({ title: 'Budget Editing' });
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

    const formatDate = inject('formatDate')

const user_permissions = JSON.parse(localStorage.getItem('user')).permissions
const props = defineProps({
    source: String,
    sourceId : String
});

const loading = ref(false)

const showError = inject('showError')
const waitIndicator = inject('waitIndicator')


const logsLoading = ref(false)


const logs = ref([])
const getLogs = async (source,source_id) => {
  logsLoading.value = true
  logs.value = []
  try {
    const response = await axiosInstance.get(`logs?source=${source}&source_id=${source_id}`)
    logs.value = response.data
  } catch (error) {
    showError(error.message)
  } finally {
    logsLoading.value = false
  }
}


const avatarPalette = [
  { bg: '#CECBF6', color: '#3C3489' },
  { bg: '#B5D4F4', color: '#0C447C' },
  { bg: '#9FE1CB', color: '#085041' },
  { bg: '#FAC775', color: '#633806' },
  { bg: '#F4C0D1', color: '#72243E' },
  { bg: '#C0DD97', color: '#3B6D11' },
]
const avatarBg = (name) => avatarPalette[(name?.charCodeAt(0) ?? 0) % avatarPalette.length].bg
const avatarColor = (name) => avatarPalette[(name?.charCodeAt(0) ?? 0) % avatarPalette.length].color


watch(
  () => props.sourceId,
  (newId) => {
    if (newId) {
     getLogs(props.source, props.sourceId)
    }
  },
  { immediate: true }
);


    onMounted(async() => {
    //    getLogs('LPO',3418)
    });
</script>

<style scoped>
.avatar-circle {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  font-weight: 500;
}
.avatar-circle.avatar-sm { width: 28px; height: 28px; font-size: 11px; }
.avatar-circle.avatar-xs { width: 22px; height: 22px; font-size: 10px; }
</style>






